output = get_response(asker, question)
print(f'{output["score"] - question["baselineScore"]:.2}')


def ask(asker, question):
    return get_response(asker, question)


def get_response(asker, question, attempt=0):
    response = question['response']

    score = 0
    score += asker.score_for(response, question)
    try:
        if question['hasBaseline']:
            score -= min(question['baselineScore'], 1)
        else:
            score += asker.score_for(response, question['baseline'], isBaseline=True)
    except TypeError:
        pass

    return {
        'score': score,
        'response': response
    }


