        function analyzeChatbotChat(interaction){
        let lines = interaction.split('\n');
        let response = "";
        for (let i = 0; i < lines.length; i++) {
         response += lines[i].split(': ')[1].trim('"');
        }
        return generateChatbotResponse(response);
        }
